WITH s AS (SELECT * FROM steals WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), u AS (SELECT ability, success, item_id, gil FROM s GROUP BY actor_id, target_id, ability, success, item_id, gil, message, intDiv(ts_ms, 60000)), rl AS (SELECT max(release) AS release FROM captures WHERE capture_id IN (SELECT capture_id FROM s)) SELECT u.ability AS ability, u.success AS success, u.item_id AS item, any(i.name) AS item_name, count() AS n, sum(u.gil) AS gil FROM u LEFT JOIN (SELECT id, name FROM item_names WHERE release = (SELECT release FROM rl)) i ON i.id = u.item_id GROUP BY u.ability, u.success, u.item_id ORDER BY u.ability, u.success DESC, n DESC
